export class VoxelWorld{
 constructor(options={}){this.mode=options.mode||'creative';this.blocks=new Map();this.inventory={1:40,2:30,3:25,4:20,5:20};this.selected=1;this.collected=[];this.crystals=[[-9,-8],[8,-7],[-7,8],[9,9],[0,-10]];for(let x=-12;x<=12;x++)for(let z=-12;z<=12;z++){const h=2+Math.floor((Math.sin(x*.4)+Math.cos(z*.42)+2)*.8);for(let y=0;y<=h;y++)this.set(x,y,z,y===h?1:2)}for(const [x,z]of [[-6,-5],[6,4],[-8,5],[8,-3]]){const h=this.top(x,z)-.5;for(let y=h+1;y<h+5;y++)this.set(x,y,z,3);for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++)for(let dy=4;dy<=5;dy++)this.set(x+dx,h+dy,z+dz,6)}this.player={x:0,y:this.top(0,0)+1.01,z:0,vy:0,ground:false};this.edits=0;this.completed=false}
 key(x,y,z){return `${x},${y},${z}`}get(x,y,z){return this.blocks.get(this.key(x,y,z))||0}set(x,y,z,type){if(type)this.blocks.set(this.key(x,y,z),type);else this.blocks.delete(this.key(x,y,z))}top(x,z){for(let y=20;y>=0;y--)if(this.get(Math.round(x),y,Math.round(z)))return y+.5;return -2}
 solid(x,y,z){const radius=.28;for(const dx of [-radius,radius])for(const dz of [-radius,radius])for(const dy of [.05,1.5])if(this.get(Math.round(x+dx),Math.round(y+dy),Math.round(z+dz)))return true;return false}
 edit(x,y,z,place=false){x=Math.round(x);y=Math.round(y);z=Math.round(z);const p=this.player;if(Math.hypot(x-p.x,y-p.y,z-p.z)>7||Math.abs(x)>13||Math.abs(z)>13||y<1||y>15)return false;if(place){if(this.get(x,y,z)||Math.abs(x-p.x)<.8&&Math.abs(z-p.z)<.8&&y>p.y-.6&&y<p.y+2)return false;if(this.mode!=='creative'&&!this.inventory[this.selected])return false;this.set(x,y,z,this.selected);if(this.mode!=='creative')this.inventory[this.selected]--}else{const type=this.get(x,y,z);if(!type)return false;this.set(x,y,z,0);const t=type===6?1:type;this.inventory[t]=(this.inventory[t]||0)+1}this.edits++;return true}
 update(dt,keys=new Set(),pressed=new Set(),yaw=0){const p=this.player;let x=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),z=(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0),length=Math.hypot(x,z)||1;x/=length;z/=length;const speed=keys.has('ShiftLeft')?6:4,dx=(Math.cos(yaw)*x-Math.sin(yaw)*z)*speed*dt,dz=(-Math.sin(yaw)*x-Math.cos(yaw)*z)*speed*dt;if(!this.solid(p.x+dx,p.y,p.z))p.x+=dx;if(!this.solid(p.x,p.y,p.z+dz))p.z+=dz;if(pressed.has('Space')&&p.ground){p.vy=8;p.ground=false}p.vy-=22*dt;const ny=p.y+p.vy*dt;if(!this.solid(p.x,ny,p.z)){p.y=ny;p.ground=false}else{if(p.vy<0)p.ground=true;p.vy=0}if(p.y<-8||Math.abs(p.x)>15||Math.abs(p.z)>15)this.respawn();for(let i=0;i<5;i++){const [cx,cz]=this.crystals[i];if(!this.collected.includes(i)&&Math.hypot(p.x-cx,p.z-cz)<1.6&&Math.abs(p.y-this.top(cx,cz))<3)this.collected.push(i)}this.completed=this.collected.length===5;for(let i=1;i<=5;i++)if(pressed.has('Digit'+i))this.selected=i;if(pressed.has('Tab'))this.selected=this.selected%5+1;if(pressed.has('KeyR'))this.respawn()}
 respawn(){this.player={x:0,y:this.top(0,0)+1.1,z:0,vy:0,ground:false}}
 save(){return JSON.stringify({version:1,blocks:[...this.blocks],inventory:this.inventory,selected:this.selected,collected:this.collected,player:this.player,edits:this.edits})}
 load(text){try{const d=JSON.parse(text);if(d.version!==1||!Array.isArray(d.blocks)||d.blocks.length>15000)return false;const b=new Map();for(const [key,value]of d.blocks){if(typeof key!=='string'||!/^(-?\d+),(-?\d+),(-?\d+)$/.test(key)||!Number.isInteger(value)||value<1||value>6)return false;const [x,y,z]=key.split(',').map(Number);if(Math.abs(x)>14||Math.abs(z)>14||y<0||y>20)return false;b.set(key,value)}this.blocks=b;this.inventory=Object.fromEntries([1,2,3,4,5].map(i=>[i,Math.max(0,Math.min(9999,Number(d.inventory?.[i])||0))]));this.collected=Array.isArray(d.collected)?[...new Set(d.collected.filter(x=>Number.isInteger(x)&&x>=0&&x<5))]:[];this.selected=Math.max(1,Math.min(5,Number(d.selected)||1));this.edits=Number(d.edits)||0;this.respawn();return true}catch{return false}}
}
